export interface Monoid<T> {
  readonly identity: T;
  readonly combine: (a: T, b: T) => T;   // total: no throw, no undefined
}

export const fold = <T,>(xs: readonly T[], m: Monoid<T>): T =>
  xs.reduce(m.combine, m.identity);          // identity is required by the signature

const sum: Monoid<number> = { identity: 0, combine: (a, b) => a + b };
const cat: Monoid<readonly string[]> = { identity: [], combine: (a, b) => a.concat(b) };

// law tests are ordinary tests
it('is a monoid', () => {
  property('left identity', fc.array(fc.integer()).prop(a => sum.combine(sum.identity, a) === a));
  property('associativity', fc.array(fc.integer()).prop(xs =>
    fold(xs, sum) === fold(fold(xs, sum), sum)));
});
